import { Injectable } from '@angular/core';

import Decimal from 'decimal.js';

@Injectable({
    providedIn: 'root'
})
export class DecimalService {

    constructor() { }

    add(num1: number, num2: number): number {
        const dec1 = new Decimal(num1);
        const dec2 = new Decimal(num2);
        return dec1.add(dec2).toNumber();

    }

    subtract(num1: number, num2: number): number {
        const dec1 = new Decimal(num1);
        const dec2 = new Decimal(num2);
        return dec1.sub(dec2).toNumber();

    }

    multiply(num1: number, num2: number): number {
        const dec1 = new Decimal(num1);
        const dec2 = new Decimal(num2);
        return dec1.mul(dec2).toNumber();
    }

    divide(num1: number, num2: number): number {
        const dec1 = new Decimal(num1);
        const dec2 = new Decimal(num2);
        return dec1.div(dec2).toNumber();
    }

    decimal(num: number): number {
        return new Decimal(num).toNumber()
    }
}
